const{exec:exec}=require("child_process");function getCurrentKeyboardLayout(e){const t="\n    $override = Get-WinDefaultInputMethodOverride;\n    if ($override) {\n      $override\n    } else {\n      (Get-WinUserLanguageList)[0].InputMethodTips | Select-Object -First 1\n    }\n  ".replace(/\n/g," ").trim();exec(`powershell -Command "${t}"`,((t,n,r)=>{if(t)return e(null);const a=n.match(/:(\w{8})/);if(a&&a[1]){const t=a[1].toUpperCase();e(t)}else e(null)}))}function getLangPrefix(e){return e.slice(-4)}function setKeyboardLayout(e,t){const n=`\\"${getLangPrefix(e)}:${e}\\"`,r=`\n    $LangList = Get-WinUserLanguageList;\n    $NewLangList = New-WinUserLanguageList -Language $LangList[0].LanguageTag;\n    $NewLangList[0].InputMethodTips.Clear();\n    $NewLangList[0].InputMethodTips.Add("${n}");\n    Set-WinUserLanguageList $NewLangList -Force;\n    Set-WinDefaultInputMethodOverride -InputTip "${n}";\n  `.replace(/\n/g," ").trim();exec(`powershell -Command "${r}"`,((e,n,r)=>{t(!e)}))}module.exports={getCurrentKeyboardLayout:getCurrentKeyboardLayout,setKeyboardLayout:setKeyboardLayout};